public int matrixChain(int[] p) {
    int n = p.length - 1;
    return solve(p, 1, n);
}

// solve(i, j): min cost to multiply matrices i..j (1-indexed)
private int solve(int[] p, int i, int j) {
    if (i == j) {
        return 0;
    }
    int best = Integer.MAX_VALUE;
    for (int k = i; k < j; k++) {
        int cost = solve(p, i, k) + solve(p, k + 1, j) + p[i - 1] * p[k] * p[j];
        best = Math.min(best, cost);
    }
    return best;
}

