def matrix_chain(self, p: list[int]) -> int:
    from functools import lru_cache
    n = len(p) - 1

    @lru_cache(maxsize=None)
    def solve(i: int, j: int) -> int:
        if i == j:
            return 0
        best = float('inf')
        for k in range(i, j):
            cost = solve(i, k) + solve(k + 1, j) + p[i - 1] * p[k] * p[j]
            best = min(best, cost)
        return best

    return solve(1, n)

